B.aoB=new A.j(B.m,["\u0648\u064e\u0623\u064e\u0648\u0652\u062d\u064e\u064a\u0652\u0646\u064e\u0627 \u0625\u0650\u0644\u064e\u0649 \u0645\u064f\u0648\u0633\u064e\u0649 \u0623\u064e\u0646\u0652 \u0623\u064e\u0644\u0652\u0642\u0650 \u0639\u064e\u0635\u064e\u0627\u0643\u064e \u0641\u064e\u0625\u0650\u0630\u064e\u0627 \u0647\u0650\u064a\u064e \u062a\u064e\u0644\u0652\u0642\u064e\u0641\u064f \u0645\u064e\u0627 \u064a\u064e\u0623\u0652\u0641\u0650\u0643\u064f\u0648\u0646\u064e (117) \u0641\u064e\u0648\u064e\u0642\u0639\u064e \u0627\u0644\u0652\u062d\u064e\u0642\u0651\u064f \u0648\u064e\u0628\u064e\u0637\u064e\u0644\u064e \u0645\u064e\u0627 \u0643\u064e\u0627\u0646\u064f\u0648\u0627 \u064a\u064e\u0639\u0652\u0645\u064e\u0644\u064f\u0648\u0646\u064e (118) \u0641\u064e\u063a\u064f\u0644\u0650\u0628\u064f\u0648\u0627 \u0647\u064f\u0646\u064e\u0627\u0644\u0650\u0643\u064e \u0648\u064e\u0627\u0646\u0652\u0642\u064e\u0644\u064e\u0628\u064f\u0648\u0627 \u0635\u064e\u0627\u063a\u0650\u0631\u0650\u064a\u0646\u064e (119) \u0648\u064e\u0623\u064f\u0644\u0652\u0642\u0650\u064a\u064e \u0627\u0644\u0633\u0651\u064e\u062d\u064e\u0631\u064e\u0629\u064f \u0633\u064e\u0627\u062c\u0650\u062f\u0650\u064a\u0646\u064e (120) \u0642\u064e\u0627\u0644\u064f\u0648\u0627 \u0622\u0645\u064e\u0646\u0651\u064e\u0627 \u0628\u0650\u0631\u064e\u0628\u0651\u0650 \u0627\u0644\u0652\u0639\u064e\u0627\u0644\u064e\u0645\u0650\u064a\u0646\u064e (121) \u0631\u064e\u0628\u0651\u0650 \u0645\u064f\u0648\u0633\u064e\u0649 \u0648\u064e\u0647\u064e\u0627\u0631\u064f\u0648\u0646\u064e (122)","\u0627\u0644\u0623\u0639\u0631\u0627\u0641 117-122: \u0622\u064a\u0627\u062a \u0625\u0628\u0637\u0627\u0644 \u0627\u0644\u0633\u062d\u0631",1],t.R)
B.aom=new A.j(B.m,["\u0641\u064e\u0644\u064e\u0645\u0651\u064e\u0627 \u0623\u064e\u0644\u0652\u0642\u064e\u0648\u0652\u0627 \u0642\u064e\u0627\u0644\u064e \u0645\u064f\u0648\u0633\u064e\u0649 \u0645\u064e\u0627 \u062c\u0650\u0626\u0652\u062a\u064f\u0645\u0652 \u0628\u0650\u0647\u0650 \u0627\u0644\u0633\u0651\u0650\u062d\u0652\u0631\u064f \u0625\u0650\u0646\u0651\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u064e \u0633\u064e\u064a\u064f\u0628\u0652\u0637\u0650\u0644\u064f\u0647\u064f \u0625\u0650\u0646\u0651\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u064e \u0644\u064e\u0627 \u064a\u064f\u0635\u0652\u0644\u0650\u062d\u064f \u0639\u064e\u0645\u064e\u0644\u064e \u0627\u0644\u0652\u0645\u064f\u0641\u0652\u0633\u0650\u062f\u0650\u064a\u0646\u064e (81) \u0648\u064e\u064a\u064f\u062d\u0650\u0642\u0651\u064f \u0627\u0644\u0644\u0651\u064e\u0647\u064f \u0627\u0644\u0652\u062d\u064e\u0642\u0651\u064e \u0628\u0650\u0643\u064e\u0644\u0650\u0645\u064e\u0627\u062a\u0650\u0647\u0650 \u0648\u064e\u0644\u064e\u0648\u0652 \u0643\u064e\u0631\u0650\u0647\u064e \u0627\u0644\u0652\u0645\u064f\u062c\u0652\u0631\u0650\u0645\u064f\u0648\u0646\u064e (82)","\u064a\u0648\u0646\u0633 81-82: \u0625\u0628\u0637\u0627\u0644 \u0627\u0644\u0633\u062d\u0631",1],t.R)
B.aoj=new A.j(B.m,["\u0648\u064e\u0623\u064e\u0644\u0652\u0642\u0650 \u0645\u064e\u0627 \u0641\u0650\u064a \u064a\u064e\u0645\u0650\u064a\u0646\u0650\u0643\u064e \u062a\u064e\u0644\u0652\u0642\u064e\u0641\u0652 \u0645\u064e\u0627 \u0635\u064e\u0646\u064e\u0639\u064f\u0648\u0627 \u0625\u0650\u0646\u0651\u064e\u0645\u064e\u0627 \u0635\u064e\u0646\u064e\u0639\u064f\u0648\u0627 \u0643\u064e\u064a\u0652\u062f\u064f \u0633\u064e\u0627\u062d\u0650\u0631\u064d \u0648\u064e\u0644\u064e\u0627 \u064a\u064f\u0641\u0652\u0644\u0650\u062d\u064f \u0627\u0644\u0633\u0651\u064e\u0627\u062d\u0650\u0631\u064f \u062d\u064e\u064a\u0652\u062b\u064f \u0623\u064e\u062a\u064e\u0649 (69)","\u0633\u0648\u0631\u0629 \u0637\u0647 \u0622\u064a\u0629 69: \u0625\u0628\u0637\u0627\u0644 \u0627\u0644\u0633\u062d\u0631",1],t.R)
B.ao8=new A.j(B.m,["\u0623\u064e\u0641\u064e\u062d\u064e\u0633\u0650\u0628\u0652\u062a\u064f\u0645\u0652 \u0623\u064e\u0646\u0651\u064e\u0645\u064e\u0627 \u062e\u064e\u0644\u064e\u0642\u0652\u0646\u064e\u0627\u0643\u064f\u0645\u0652 \u0639\u064e\u0628\u064e\u062b\u064b\u0627 \u0648\u064e\u0623\u064e\u0646\u0651\u064e\u0643\u064f\u0645\u0652 \u0625\u0650\u0644\u064e\u064a\u0652\u0646\u064e\u0627 \u0644\u064e\u0627 \u062a\u064f\u0631\u0652\u062c\u064e\u0639\u064f\u0648\u0646\u064e (115) \u0641\u064e\u062a\u064e\u0639\u064e\u0627\u0644\u064e\u0649 \u0627\u0644\u0644\u0651\u064e\u0647\u064f \u0627\u0644\u0652\u0645\u064e\u0644\u0650\u0643\u064f \u0627\u0644\u0652\u062d\u064e\u0642\u0651\u064f \u0644\u064e\u0627 \u0625\u0650\u0644\u064e\u0647\u064e \u0625\u0650\u0644\u0651\u064e\u0627 \u0647\u064f\u0648\u064e \u0631\u064e\u0628\u0651\u064f \u0627\u0644\u0652\u0639\u064e\u0631\u0652\u0634\u0650 \u0627\u0644\u0652\u0643\u064e\u0631\u0650\u064a\u0645\u0650 (116) \u0648\u064e\u0645\u064e\u0646\u0652 \u064a\u064e\u062f\u0652\u0639\u064f \u0645\u064e\u0639\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u0625\u0650\u0644\u064e\u0647\u064b\u0627 \u0622\u062e\u064e\u0631\u064e \u0644\u064e\u0627 \u0628\u064f\u0631\u0652\u0647\u064e\u0627\u0646\u064e \u0644\u064e\u0647\u064f \u0628\u0650\u0647\u0650 \u0641\u064e\u0625\u0650\u0646\u0651\u064e\u0645\u064e\u0627 \u062d\u0650\u0633\u064e\u0627\u0628\u064f\u0647\u064f \u0639\u0650\u0646\u0652\u062f\u064e \u0631\u064e\u0628\u0651\u0650\u0647\u0650 \u0625\u0650\u0646\u0651\u064e\u0647\u064f \u0644\u064e\u0627 \u064a\u064f\u0641\u0652\u0644\u0650\u062d\u064f \u0627\u0644\u0652\u0643\u064e\u0627\u0641\u0650\u0631\u064f\u0648\u0646\u064e (117) \u0648\u064e\u0642\u064f\u0644\u0652 \u0631\u064e\u0628\u0651\u0650 \u0627\u063a\u0652\u0641\u0650\u0631\u0652 \u0648\u064e\u0627\u0631\u0652\u062d\u064e\u0645\u0652 \u0648\u064e\u0623\u064e\u0646\u0652\u062a\u064e \u062e\u064e\u064a\u0652\u0631\u064f \u0627\u0644\u0631\u0651\u064e\u0627\u062d\u0650\u0645\u0650\u064a\u0646\u064e (118)","\u0627\u0644\u0645\u0624\u0645\u0646\u0648\u0646 115-118: \u0622\u064a\u0627\u062a \u0627\u0644\u0647\u062f\u0627\u064a\u0629 \u0648\u0627\u0644\u0633\u0643\u064a\u0646\u0629",1],t.R)
B.aoh=new A.j(B.m,["\u0648\u064e\u0627\u0644\u0635\u0651\u064e\u0627\u0641\u0651\u064e\u0627\u062a\u0650 \u0635\u064e\u0641\u0651\u064b\u0627 (1) \u0641\u064e\u0627\u0644\u0632\u0651\u064e\u0627\u062c\u0650\u0631\u064e\u0627\u062a\u0650 \u0632\u064e\u062c\u0652\u0631\u064b\u0627 (2) \u0641\u064e\u0627\u0644\u062a\u0651\u064e\u0627\u0644\u0650\u064a\u064e\u0627\u062a\u0650 \u0630\u0650\u0643\u0652\u0631\u064b\u0627 (3) \u0625\u0650\u0646\u0651\u064e \u0625\u0650\u0644\u064e\u0647\u064e\u0643\u064f\u0645\u0652 \u0644\u064e\u0648\u064e\u0627\u062d\u0650\u062f\u064c (4) \u0631\u064e\u0628\u0651\u064f \u0627\u0644\u0633\u0651\u064e\u0645\u064e\u0627\u0648\u064e\u0627\u062a\u0650 \u0648\u064e\u0627\u0644\u0652\u0623\u064e\u0631\u0652\u0636\u0650 \u0648\u064e\u0645\u064e\u0627 \u0628\u064e\u064a\u0652\u0646\u064e\u0647\u064f\u0645\u064e\u0627 \u0648\u064e\u0631\u064e\u0628\u0651\u064f \u0627\u0644\u0652\u0645\u064e\u0634\u064e\u0627\u0631\u0650\u0642\u0650 (5) \u0625\u0650\u0646\u0651\u064e\u0627 \u0632\u064e\u064a\u0651\u064e\u0646\u0651\u064e\u0627 \u0627\u0644\u0633\u0651\u064e\u0645\u064e\u0627\u0621\u064e \u0627\u0644\u062f\u0651\u064f\u0646\u0652\u064a\u064e\u0627 \u0628\u0650\u0632\u0650\u064a\u0646\u064e\u0629\u0650 \u0627\u0644\u0652\u0643\u064e\u0648\u064e\u0627\u0643\u0650\u0628\u0650 (6) \u0648\u064e\u062d\u0650\u0641\u0652\u0638\u064b\u0627 \u0645\u0650\u0646\u0652 \u0643\u064f\u0644\u0651\u0650 \u0634\u064e\u064a\u0652\u0637\u064e\u0627\u0646\u064d \u0645\u064e\u0627\u0631\u0650\u062f\u064d (7) \u0644\u064e\u0627 \u064a\u064e\u0633\u0651\u064e\u0645\u0651\u064e\u0639\u064f\u0648\u0646\u064e \u0625\u0650\u0644\u064e\u0649 \u0627\u0644\u0652\u0645\u064e\u0644\u064e\u0625\u0650 \u0627\u0644\u0652\u0623\u064e\u0639\u0652\u0644\u064e\u0649 \u0648\u064e\u064a\u064f\u0642\u0652\u0630\u064e\u0641\u064f\u0648\u0646\u064e \u0645\u0650\u0646\u0652 \u0643\u064f\u0644\u0651\u0650 \u062c\u064e\u0627\u0646\u0650\u0628\u064d (8) \u062f\u064f\u062d\u064f\u0648\u0631\u064b\u0627 \u0648\u064e\u0644\u064e\u0647\u064f\u0645\u0652 \u0639\u064e\u0630\u064e\u0627\u0628\u064c \u0648\u064e\u0627\u0635\u0650\u0628\u064c (9) \u0625\u0650\u0644\u0651\u064e\u0627 \u0645\u064e\u0646\u0652 \u062e\u064e\u0637\u0650\u0641\u064e \u0627\u0644\u0652\u062e\u064e\u0637\u0652\u0641\u064e\u0629\u064e \u0641\u064e\u0623\u064e\u062a\u0652\u0628\u064e\u0639\u064e\u0647\u064f \u0634\u0650\u0647\u064e\u0627\u0628\u064c \u062b\u064e\u0627\u0642\u0650\u0628\u064c (10)","\u0623\u0648\u0644 10 \u0622\u064a\u0627\u062a \u0645\u0646 \u0633\u0648\u0631\u0629 \u0627\u0644\u0635\u0627\u0641\u0627\u062a: \u0637\u0631\u062f \u0627\u0644\u0634\u064a\u0627\u0637\u064a\u0646",1],t.R)
B.apm=new A.j(B.m,["\u0648\u064e\u0625\u0650\u0630\u0652 \u0635\u064e\u0631\u064e\u0641\u0652\u0646\u064e\u0627 \u0625\u0650\u0644\u064e\u064a\u0652\u0643\u064e \u0646\u064e\u0641\u064e\u0631\u064b\u0627 \u0645\u0650\u0646\u064e \u0627\u0644\u0652\u062c\u0650\u0646\u0651\u0650 \u064a\u064e\u0633\u0652\u062a\u064e\u0645\u0650\u0639\u064f\u0648\u0646\u064e \u0627\u0644\u0652\u0642\u064f\u0631\u0652\u0622\u0646\u064e \u0641\u064e\u0644\u064e\u0645\u0651\u064e\u0627 \u062d\u064e\u0636\u064e\u0631\u064f\u0648\u0647\u064f \u0642\u064e\u0627\u0644\u064f\u0648\u0627 \u0623\u064e\u0646\u0652\u0635\u0650\u062a\u064f\u0648\u0627 \u0641\u064e\u0644\u064e\u0645\u0651\u064e\u0627 \u0642\u064f\u0636\u0650\u064a\u064e \u0648\u064e\u0644\u0651\u064e\u0648\u0652\u0627 \u0625\u0650\u0644\u064e\u0649 \u0642\u064e\u0648\u0652\u0645\u0650\u0647\u0650\u0645\u0652 \u0645\u064f\u0646\u0652\u0630\u0650\u0631\u0650\u064a\u0646\u064e (29) \u0642\u064e\u0627\u0644\u064f\u0648\u0627 \u064a\u064e\u0627 \u0642\u064e\u0648\u0652\u0645\u064e\u0646\u064e\u0627 \u0625\u0650\u0646\u0651\u064e\u0627 \u0633\u064e\u0645\u0650\u0639\u0652\u0646\u064e\u0627 \u0643\u0650\u062a\u064e\u0627\u0628\u064b\u0627 \u0623\u064f\u0646\u0652\u0632\u0650\u0644\u064e \u0645\u0650\u0646\u0652 \u0628\u064e\u0639\u0652\u062f\u0650 \u0645\u064f\u0648\u0633\u064e\u0649 \u0645\u064f\u0635\u064e\u062f\u0651\u0650\u0642\u064b\u0627 \u0644\u0650\u0645\u064e\u0627 \u0628\u064e\u064a\u0652\u0646\u064e \u064a\u064e\u062f\u064e\u064a\u0652\u0647\u0650 \u064a\u064e\u0647\u0652\u062f\u0650\u064a \u0625\u0650\u0644\u064e\u0649 \u0627\u0644\u0652\u062d\u064e\u0642\u0651\u0650 \u0648\u064e\u0625\u0650\u0644\u064e\u0649 \u0637\u064e\u0631\u0650\u064a\u0642\u064d \u0645\u064f\u0633\u0652\u062a\u064e\u0642\u0650\u064a\u0645\u064d (30) \u064a\u064e\u0627 \u0642\u064e\u0648\u0652\u0645\u064e\u0646\u064e\u0627 \u0623\u064e\u062c\u0650\u064a\u0628\u064f\u0648\u0627 \u062f\u064e\u0627\u0639\u0650\u064a\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u0648\u064e\u0622\u0645\u0650\u0646\u064f\u0648\u0627 \u0628\u0650\u0647\u0650 \u064a\u064e\u063a\u0652\u0641\u0650\u0631\u0652 \u0644\u064e\u0643\u064f\u0645\u0652 \u0645\u0650\u0646\u0652 \u0630\u064f\u0646\u064f\u0648\u0628\u0650\u0643\u064f\u0645\u0652 \u0648\u064e\u064a\u064f\u062c\u0650\u0631\u0652\u0643\u064f\u0645\u0652 \u0645\u0650\u0646\u0652 \u0639\u064e\u0630\u064e\u0627\u0628\u064d \u0623\u064e\u0644\u0650\u064a\u0645\u064d (31) \u0648\u064e\u0645\u064e\u0646\u0652 \u0644\u064e\u0627 \u064a\u064f\u062c\u0650\u0628\u0652 \u062f\u064e\u0627\u0639\u0650\u064a\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u0641\u064e\u0644\u064e\u064a\u0652\u0633\u064e \u0628\u0650\u0645\u064f\u0639\u0652\u062c\u0650\u0632\u064d \u0641\u0650\u064a \u0627\u0644\u0652\u0623\u064e\u0631\u0652\u0636\u0650 \u0648\u064e\u0644\u064e\u064a\u0652\u0633\u064e \u0644\u064e\u0647\u064f \u0645\u0650\u0646\u0652 \u062f\u064f\u0648\u0646\u0650\u0647\u0650 \u0623\u064e\u0648\u0652\u0644\u0650\u064a\u064e\u0627\u0621\u064f \u0623\u064f\u0648\u0644\u064e\u0626\u0650\u0643\u064e \u0641\u0650\u064a \u0636\u064e\u0644\u064e\u0627\u0644\u064d \u0645\u064f\u0628\u0650\u064a\u0646\u064d (32)","\u0633\u0648\u0631\u0629 \u0627\u0644\u0623\u062d\u0642\u0627\u0641 29-32: \u0622\u064a\u0627\u062a \u0627\u0644\u062c\u0646",1],t.R)
B.aqb=new A.j(B.m,["\u064a\u064e\u0627 \u0645\u064e\u0639\u0652\u0634\u064e\u0631\u064e \u0627\u0644\u0652\u062c\u0650\u0646\u0651\u0650 \u0648\u064e\u0627\u0644\u0652\u0625\u0650\u0646\u0652\u0633\u0650 \u0625\u0650\u0646\u0650 \u0627\u0633\u0652\u062a\u064e\u0637\u064e\u0639\u0652\u062a\u064f\u0645\u0652 \u0623\u064e\u0646\u0652 \u062a\u064e\u0646\u0652\u0641\u064f\u0630\u064f\u0648\u0627 \u0645\u0650\u0646\u0652 \u0623\u064e\u0642\u0652\u0637\u064e\u0627\u0631\u0650 \u0627\u0644\u0633\u0651\u064e\u0645\u064e\u0627\u0648\u064e\u0627\u062a\u0650 \u0648\u064e\u0627\u0644\u0652\u0623\u064e\u0631\u0652\u0636\u0650 \u0641\u064e\u0627\u0646\u0652\u0641\u064f\u0630\u064f\u0648\u0627 \u0644\u064e\u0627 \u062a\u064e\u0646\u0652\u0641\u064f\u0630\u064f\u0648\u0646\u064e \u0625\u0650\u0644\u0651\u064e\u0627 \u0628\u0650\u0633\u064f\u0644\u0652\u0637\u064e\u0627\u0646\u064d (33) \u0641\u064e\u0628\u0650\u0623\u064e\u064a\u0651\u0650 \u0622\u0644\u064e\u0627\u0621\u0650 \u0631\u064e\u0628\u0651\u0650\u0643\u064f\u0645\u064e\u0627 \u062a\u064f\u0643\u064e\u0630\u0651\u0650\u0628\u064e\u0627\u0646\u0650 (34) \u064a\u064f\u0631\u0652\u0633\u064e\u0644\u064f \u0639\u064e\u0644\u064e\u064a\u0652\u0643\u064f\u0645\u064e\u0627 \u0634\u064f\u0648\u064e\u0627\u0638\u064c \u0645\u0650\u0646\u0652 \u0646\u064e\u0627\u0631\u064d \u0648\u064e\u0646\u064f\u062d\u064e\u0627\u0633\u064c \u0641\u064e\u0644\u064e\u0627 \u062a\u064e\u0646\u0652\u062a\u064e\u0635\u0650\u0631\u064e\u0627\u0646\u0650 (35) \u0641\u064e\u0628\u0650\u0623\u064e\u064a\u0651\u0650 \u0622\u0644\u064e\u0627\u0621\u0650 \u0631\u064e\u0628\u0651\u0650\u0643\u064f\u0645\u064e\u0627 \u062a\u064f\u0643\u064e\u0630\u0651\u0650\u0628\u064e\u0627\u0646\u0650 (36)","\u0633\u0648\u0631\u0629 \u0627\u0644\u0631\u062d\u0645\u0646 33-36: \u0622\u064a\u0627\u062a \u0627\u0644\u062a\u062d\u062f\u064a \u0648\u0627\u0644\u062a\u062d\u0635\u064a\u0646",1],t.R)
B.aoc=new A.j(B.m,["\u0644\u064e\u0648\u0652 \u0623\u064e\u0646\u0652\u0632\u064e\u0644\u0652\u0646\u064e\u0627 \u0647\u064e\u0630\u064e\u0627 \u0627\u0644\u0652\u0642\u064f\u0631\u0652\u0622\u0646\u064e \u0639\u064e\u0644\u064e\u0649 \u062c\u064e\u0628\u064e\u0644\u064d \u0644\u064e\u0631\u064e\u0623\u064e\u064a\u0652\u062a\u064e\u0647\u064f \u062e\u064e\u0627\u0634\u0650\u0639\u064b\u0627 \u0645\u064f\u062a\u064e\u0635\u064e\u062f\u0651\u0650\u0639\u064b\u0627 \u0645\u0650\u0646\u0652 \u062e\u064e\u0634\u0652\u064a\u064e\u0629\u0650 \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u0648\u064e\u062a\u0650\u0644\u0652\u0643\u064e \u0627\u0644\u0652\u0623\u064e\u0645\u0652\u062b\u064e\u0627\u0644\u064f \u0646\u064e\u0636\u0652\u0631\u0650\u0628\u064f\u0647\u064e\u0627 \u0644\u0650\u0644\u0646\u0651\u064e\u0627\u0633\u0650 \u0644\u064e\u0639\u064e\u0644\u0651\u064e\u0647\u064f\u0645\u0652 \u064a\u064e\u062a\u064e\u0641\u064e\u0643\u0651\u064e\u0631\u064f\u0648\u0646\u064e (21) \u0647\u064f\u0648\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u064f \u0627\u0644\u0651\u064e\u0630\u0650\u064a \u0644\u064e\u0627 \u0625\u0650\u0644\u064e\u0647\u064e \u0625\u0650\u0644\u0651\u064e\u0627 \u0647\u064f\u0648\u064e \u0639\u064e\u0627\u0644\u0650\u0645\u064f \u0627\u0644\u0652\u063a\u064e\u064a\u0652\u0628\u0650 \u0648\u064e\u0627\u0644\u0634\u0651\u064e\u0647\u064e\u0627\u062f\u064e\u0629\u0650 \u0647\u064f\u0648\u064e \u0627\u0644\u0631\u0651\u064e\u062d\u0652\u0645\u064e\u0646\u064f \u0627\u0644\u0631\u0651\u064e\u062d\u0650\u064a\u0645\u064f (22) \u0647\u064f\u0648\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u064f \u0627\u0644\u0651\u064e\u0630\u0650\u064a \u0644\u064e\u0627 \u0625\u0650\u0644\u064e\u0647\u064e \u0625\u0650\u0644\u0651\u064e\u0627 \u0647\u064f\u0648\u064e \u0627\u0644\u0652\u0645\u064e\u0644\u0650\u0643\u064f \u0627\u0644\u0652\u0642\u064f\u062f\u0651\u064f\u0648\u0633\u064f \u0627\u0644\u0633\u0651\u064e\u0644\u064e\u0627\u0645\u064f \u0627\u0644\u0652\u0645\u064f\u0624\u0652\u0645\u0650\u0646\u064f \u0627\u0644\u0652\u0645\u064f\u0647\u064e\u064a\u0652\u0645\u0650\u0646\u064f \u0627\u0644\u0652\u0639\u064e\u0632\u0650\u064a\u0632\u064f \u0627\u0644\u0652\u062c\u064e\u0628\u0651\u064e\u0627\u0631\u064f \u0627\u0644\u0652\u0645\u064f\u062a\u064e\u0643\u064e\u0628\u0651\u0650\u0631\u064f \u0633\u064f\u0628\u0652\u062d\u064e\u0627\u0646\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u0639\u064e\u0645\u0651\u064e\u0627 \u064a\u064f\u0634\u0652\u0631\u0650\u0643\u064f\u0648\u0646\u064e (23) \u0647\u064f\u0648\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u064f \u0627\u0644\u0652\u062e\u064e\u0627\u0644\u0650\u0642\u064f \u0627\u0644\u0652\u0628\u064e\u0627\u0631\u0650\u0626\u064f \u0627\u0644\u0652\u0645\u064f\u0635\u064e\u0648\u0651\u0650\u0631\u064f \u0644\u064e\u0647\u064f \u0627\u0644\u0652\u0623\u064e\u0633\u0652\u0645\u064e\u0627\u0621\u064f \u0627\u0644\u0652\u062d\u064f\u0633\u0652\u0646\u064e\u0649 \u064a\u064f\u0633\u064e\u0628\u0651\u0650\u062d\u064f \u0644\u064e\u0647\u064f \u0645\u064e\u0627 \u0641\u0650\u064a \u0627\u0644\u0633\u0651\u064e\u0645\u064e\u0627\u0648\u064e\u0627\u062a\u0650 \u0648\u064e\u0627\u0644\u0652\u0623\u064e\u0631\u0652\u0636\u0650 \u0648\u064e\u0647\u064f\u0648\u064e \u0627\u0644\u0652\u0639\u064e\u0632\u0650\u064a\u0632\u064f \u0627\u0644\u0652\u062d\u064e\u0643\u0650\u064a\u0645\u064f (24)","\u062e\u0648\u0627\u062a\u064a\u0645 \u0633\u0648\u0631\u0629 \u0627\u0644\u062d\u0634\u0631: \u0622\u064a\u0627\u062a \u0627\u0644\u062e\u0634\u0648\u0639 \u0648\u0627\u0644\u0639\u0638\u0645\u0629",1],t.R)
B.aoX=new A.j(B.m,["\u0642\u064f\u0644\u0652 \u0623\u064f\u0648\u062d\u0650\u064a\u064e \u0625\u0650\u0644\u064e\u064a\u0651\u064e \u0623\u064e\u0646\u0651\u064e\u0647\u064f \u0627\u0633\u0652\u062a\u064e\u0645\u064e\u0639\u064e \u0646\u064e\u0641\u064e\u0631\u064c \u0645\u0650\u0646\u064e \u0627\u0644\u0652\u062c\u0650\u0646\u0651\u0650 \u0641\u064e\u0642\u064e\u0627\u0644\u064f\u0648\u0627 \u0625\u0650\u0646\u0651\u064e\u0627 \u0633\u064e\u0645\u0650\u0639\u0652\u0646\u064e\u0627 \u0642\u064f\u0631\u0652\u0622\u0646\u064b\u0627 \u0639\u064e\u062c\u064e\u0628\u064b\u0627 (1) \u064a\u064e\u0647\u0652\u062f\u0650\u064a \u0625\u0650\u0644\u064e\u0649 \u0627\u0644\u0631\u0651\u064f\u0634\u0652\u062f\u0650 \u0641\u064e\u0622\u0645\u064e\u0646\u0651\u064e\u0627 \u0628\u0650\u0647\u0650 \u0648\u064e\u0644\u064e\u0646\u0652 \u0646\u064f\u0634\u0652\u0631\u0650\u0643\u064e \u0628\u0650\u0631\u064e\u0628\u0651\u0650\u0646\u064e\u0627 \u0623\u064e\u062d\u064e\u062f\u064b\u0627 (2) \u0648\u064e\u0623\u064e\u0646\u0651\u064e\u0647\u064f \u062a\u064e\u0639\u064e\u0627\u0644\u064e\u0649 \u062c\u064e\u062f\u0651\u064f \u0631\u064e\u0628\u0651\u0650\u0646\u064e\u0627 \u0645\u064e\u0627 \u0627\u062a\u0651\u064e\u062e\u064e\u0630\u064e \u0635\u064e\u0627\u062d\u0650\u0628\u064e\u0629\u064b \u0648\u064e\u0644\u064e\u0627 \u0648\u064e\u0644\u064e\u062f\u064b\u0627 (3) \u0648\u064e\u0623\u064e\u0646\u0651\u064e\u0647\u064f \u0643\u064e\u0627\u0646\u064e \u064a\u064e\u0642\u064f\u0648\u0644\u064f \u0633\u064e\u0641\u0650\u064a\u0647\u064f\u0646\u064e\u0627 \u0639\u064e\u0644\u064e\u0649 \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u0634\u064e\u0637\u064e\u0637\u064b\u0627 (4) \u0648\u064e\u0623\u064e\u0646\u0651\u064e\u0627 \u0638\u064e\u0646\u064e\u0646\u0651\u064e\u0627 \u0623\u064e\u0646\u0652 \u0644\u064e\u0646\u0652 \u062a\u064e\u0642\u064f\u0648\u0644\u064e \u0627\u0644\u0652\u0625\u0650\u0646\u0652\u0633\u064f \u0648\u064e\u0627\u0644\u0652\u062c\u0650\u0646\u0651\u064f \u0639\u064e\u0644\u064e\u0649 \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u0643\u064e\u0630\u0650\u0628\u064b\u0627 (5) \u0648\u064e\u0623\u064e\u0646\u0651\u064e\u0647\u064f \u0643\u064e\u0627\u0646\u064e \u0631\u0650\u062c\u064e\u0627\u0644\u064c \u0645\u0650\u0646\u064e \u0627\u0644\u0652\u0625\u0650\u0646\u0652\u0633\u0650 \u064a\u064e\u0639\u064f\u0648\u0630\u064f\u0648\u0646\u064e \u0628\u0650\u0631\u0650\u062c\u064e\u0627\u0644\u064d \u0645\u0650\u0646\u064e \u0627\u0644\u0652\u062c\u0650\u0646\u0651\u0650 \u0641\u064e\u0632\u064e\u0627\u062f\u064f\u0648\u0647\u064f\u0645\u0652 \u0631\u064e\u0647\u064e\u0642\u064b\u0627 (6) \u0648\u064e\u0623\u064e\u0646\u0651\u064e\u0647\u064f\u0645\u0652 \u0638\u064e\u0646\u0651\u064f\u0648\u0627 \u0643\u064e\u0645\u064e\u0627 \u0638\u064e\u0646\u064e\u0646\u0652\u062a\u064f\u0645\u0652 \u0623\u064e\u0646\u0652 \u0644\u064e\u0646\u0652 \u064a\u064e\u0628\u0652\u0639\u064e\u062b\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u064f \u0623\u064e\u062d\u064e\u062f\u064b\u0627 (7) \u0648\u064e\u0623\u064e\u0646\u0651\u064e\u0627 \u0644\u064e\u0645\u064e\u0633\u0652\u0646\u064e\u0627 \u0627\u0644\u0633\u0651\u064e\u0645\u064e\u0627\u0621\u064e \u0641\u064e\u0648\u064e\u062c\u064e\u062f\u0652\u0646\u064e\u0627\u0647\u064e\u0627 \u0645\u064f\u0644\u0650\u0626\u064e\u062a\u0652 \u062d\u064e\u0631\u064e\u0633\u064b\u0627 \u0634\u064e\u062f\u0650\u064a\u062f\u064b\u0627 \u0648\u064e\u0634\u064f\u0647\u064f\u0628\u064b\u0627 (8) \u0648\u064e\u0623\u064e\u0646\u0651\u064e\u0627 \u0643\u064f\u0646\u0651\u064e\u0627 \u0646\u064e\u0642\u0652\u0639\u064f\u062f\u064f \u0645\u0650\u0646\u0652\u0647\u064e\u0627 \u0645\u064e\u0642\u064e\u0627\u0639\u0650\u062f\u064e \u0644\u0650\u0644\u0633\u0651\u064e\u0645\u0652\u0639\u0650 \u0641\u064e\u0645\u064e\u0646\u0652 \u064a\u064e\u0633\u0652\u062a\u064e\u0645\u0650\u0639\u0650 \u0627\u0644\u0652\u0622\u0646\u064e \u064a\u064e\u062c\u0650\u062f\u0652 \u0644\u064e\u0647\u064f \u0634\u0650\u0647\u064e\u0627\u0628\u064b\u0627 \u0631\u064e\u0635\u064e\u062f\u064b\u0627 (9)","\u0623\u0648\u0644 9 \u0622\u064a\u0627\u062a \u0645\u0646 \u0633\u0648\u0631\u0629 \u0627\u0644\u062c\u0646: \u0622\u064a\u0627\u062a \u0627\u0644\u062d\u0641\u0638",1],t.R)
B.apE=new A.j(B.m,["\u0628\u0650\u0633\u0652\u0645\u0650 \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u0627\u0644\u0631\u0651\u064e\u062d\u0652\u0645\u064e\u0646\u0650 \u0627\u0644\u0631\u0651\u064e\u062d\u0650\u064a\u0645\u0650. \u0642\u064f\u0644\u0652 \u0647\u064f\u0648\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u064f \u0623\u064e\u062d\u064e\u062f\u064c (1) \u0627\u0644\u0644\u0651\u064e\u0647\u064f \u0627\u0644\u0635\u0651\u064e\u0645\u064e\u062f\u064f (2) \u0644\u064e\u0645\u0652 \u064a\u064e\u0644\u0650\u062f\u0652 \u0648\u064e\u0644\u064e\u0645\u0652 \u064a\u064f\u0648\u0644\u064e\u062f\u0652 (3) \u0648\u064e\u0644\u064e\u0645\u0652 \u064a\u064e\u0643\u064f\u0646 \u0644\u0651\u064e\u0647\u064f \u0643\u064f\u0641\u064f\u0648\u064b\u0627 \u0623\u064e\u062d\u064e\u062f\u064c (4)","\u0633\u0648\u0631\u0629 \u0627\u0644\u0625\u062e\u0644\u0627\u0635: \u062a\u0639\u062f\u0644 \u062b\u0644\u062b \u0627\u0644\u0642\u0631\u0622\u0646",3],t.R)
B.aoJ=new A.j(B.m,["\u0628\u0650\u0633\u0652\u0645\u0650 \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u0627\u0644\u0631\u0651\u064e\u062d\u0652\u0645\u064e\u0646\u0650 \u0627\u0644\u0631\u0651\u064e\u062d\u0650\u064a\u0645\u0650. \u0642\u064f\u0644\u0652 \u0623\u064e\u0639\u064f\u0648\u0630\u064f \u0628\u0650\u0631\u064e\u0628\u0651\u0650 \u0627\u0644\u0652\u0641\u064e\u0644\u064e\u0642\u0650 (1) \u0645\u0650\u0646 \u0634\u064e\u0631\u0651\u0650 \u0645\u064e\u0627 \u062e\u064e\u0644\u064e\u0642\u064e (2) \u0648\u064e\u0645\u0650\u0646 \u0634\u064e\u0631\u0651\u0650 \u063a\u064e\u0627\u0633\u0650\u0642\u064d \u0625\u0650\u0630\u064e\u0627 \u0648\u064e\u0642\u064e\u0628\u064e (3) \u0648\u064e\u0645\u0650\u0646 \u0634\u064e\u0631\u0651\u0650 \u0627\u0644\u0646\u0651\u064e\u0641\u0651\u064e\u0627\u062b\u064e\u0627\u062a\u0650 \u0641\u0650\u064a \u0627\u0644\u0652\u0639\u064f\u0642\u064e\u062f\u0650 (4) \u0648\u064e\u0645\u0650\u0646 \u0634\u064e\u0631\u0651\u0650 \u062d\u064e\u0627\u0633\u0650\u062f\u064d \u0625\u0650\u0630\u064e\u0627 \u062d\u064e\u0633\u064e\u062f\u064e (5)","\u0633\u0648\u0631\u0629 \u0627\u0644\u0641\u0644\u0642: \u0644\u0644\u062d\u0641\u0638 \u0645\u0646 \u0643\u0644 \u0634\u0631",3],t.R)
